#define protected public
#include "KS/SRC/ks/FEMenu_shared.h"
#undef protected

class PreformatText {
public:
    void readText(char *filename, int max_lines, int offset);
};

class GraphicalMenuSystem;

class CreditsFrontEnd : public FEMultiMenu {
    PreformatText *credits;
    GraphicalMenuSystem *sys;
    float first_line_y;
    float x_all;
    bool up_pressed;
    bool down_pressed;

public:
    virtual void Load();
};

extern int ksGlobalTextLanguage;

enum language_t {
    LANGUAGE_FRENCH = 2,
    LANGUAGE_GERMAN = 3
};

extern "C" void stringx_append_cstr(stringx *, const char *)
    __asm__("__apl__7stringxPCc");
extern "C" void stringx_make_room(stringx *, int)
    __asm__("make_room__7stringxi");
extern "C" void stringx_append_string(stringx *, const stringx *)
    __asm__("append__7stringxRC7stringx");

inline stringx &operator+=(stringx &value, const char *text)
{
    stringx_append_cstr(&value, text);
    return value;
}

inline stringx operator+(const stringx &left, const stringx &right)
{
    stringx result;
    stringx_make_room(&result, left.my_buf->char_length + right.my_buf->char_length);
    stringx_append_string(&result, &left);
    stringx_append_string(&result, &right);
    return result;
}

