void CreditsFrontEnd::Load()
{
    FEMultiMenu::Load();

    stringx file = "credits";
    if (ksGlobalTextLanguage == LANGUAGE_FRENCH)
        file += "_fr";
    else if (ksGlobalTextLanguage == LANGUAGE_GERMAN)
        file += "_ge";
    file += ".txt";

    char *tmp = (char *)(path + file).data();

    credits->readText(tmp, 300, 10);
}
